//===----------------------------------------------------------------------===//
//
// Turn an MCInst into the four bytes of a GM32 instruction.
//
// The per-instruction bit shuffling is generated by TableGen from the Inst{}
// assignments in GPUMinInstrInfo.td (-gen-emitter).  This file supplies the
// per-operand values and decides which fixup kind an unresolved expression
// needs.
//
//===----------------------------------------------------------------------===//

#include "GPUMinFixupKinds.h"
#include "GPUMinMCTargetDesc.h"
#include "llvm/MC/MCCodeEmitter.h"
#include "llvm/MC/MCContext.h"
#include "llvm/MC/MCExpr.h"
#include "llvm/MC/MCFixup.h"
#include "llvm/MC/MCInst.h"
#include "llvm/MC/MCInstrInfo.h"
#include "llvm/MC/MCRegisterInfo.h"
#include "llvm/MC/MCSubtargetInfo.h"
#include "llvm/Support/ErrorHandling.h"

using namespace llvm;

namespace {

class GPUMinMCCodeEmitter : public MCCodeEmitter {
  MCContext &Ctx;
  const MCInstrInfo &MCII;

public:
  GPUMinMCCodeEmitter(MCContext &Ctx, const MCInstrInfo &MCII)
      : Ctx(Ctx), MCII(MCII) {}

  void encodeInstruction(const MCInst &MI, SmallVectorImpl<char> &CB,
                         SmallVectorImpl<MCFixup> &Fixups,
                         const MCSubtargetInfo &STI) const override;

  uint64_t getBinaryCodeForInstr(const MCInst &MI,
                                 SmallVectorImpl<MCFixup> &Fixups,
                                 const MCSubtargetInfo &STI) const;

  uint64_t getMachineOpValue(const MCInst &MI, const MCOperand &MO,
                             SmallVectorImpl<MCFixup> &Fixups,
                             const MCSubtargetInfo &STI) const;

  uint64_t getBranchTargetOpValue(const MCInst &MI, unsigned OpNo,
                                  SmallVectorImpl<MCFixup> &Fixups,
                                  const MCSubtargetInfo &STI) const;

  uint64_t getCallTargetOpValue(const MCInst &MI, unsigned OpNo,
                                SmallVectorImpl<MCFixup> &Fixups,
                                const MCSubtargetInfo &STI) const;
};

} // end anonymous namespace

void GPUMinMCCodeEmitter::encodeInstruction(
    const MCInst &MI, SmallVectorImpl<char> &CB,
    SmallVectorImpl<MCFixup> &Fixups, const MCSubtargetInfo &STI) const {
  if (MCII.get(MI.getOpcode()).isPseudo())
    report_fatal_error("GPUMin: cannot encode pseudo instruction " +
                       MCII.getName(MI.getOpcode()));

  uint64_t Bits = getBinaryCodeForInstr(MI, Fixups, STI);

  // GM32 is little-endian: the lowest-addressed byte holds Inst[7:0].
  unsigned Size = MCII.get(MI.getOpcode()).getSize();
  for (unsigned I = 0; I != Size; ++I)
    CB.push_back(static_cast<char>((Bits >> (8 * I)) & 0xff));
}

uint64_t GPUMinMCCodeEmitter::getMachineOpValue(
    const MCInst &MI, const MCOperand &MO, SmallVectorImpl<MCFixup> &Fixups,
    const MCSubtargetInfo &STI) const {
  if (MO.isReg())
    return Ctx.getRegisterInfo()->getEncodingValue(MO.getReg());

  if (MO.isImm())
    return static_cast<uint64_t>(MO.getImm());

  assert(MO.isExpr() && "unexpected operand kind");

  // A symbolic operand has no value yet: record a fixup and let the assembler
  // backend patch the immediate bits once layout is known.
  Fixups.push_back(MCFixup::create(/*Offset=*/0, MO.getExpr(),
                                   (MCFixupKind)gpumin::fixup_gpumin_32,
                                   /*IsPCRel=*/false));
  return 0;
}

uint64_t GPUMinMCCodeEmitter::getBranchTargetOpValue(
    const MCInst &MI, unsigned OpNo, SmallVectorImpl<MCFixup> &Fixups,
    const MCSubtargetInfo &STI) const {
  const MCOperand &MO = MI.getOperand(OpNo);
  // The displacement depends on where the word ends up, so it always goes
  // through a PC-relative fixup against a label.  The parser rejects numeric
  // operands precisely because they would need the address here.
  assert(MO.isExpr() && "branch target must be a symbol");

  Fixups.push_back(MCFixup::create(/*Offset=*/0, MO.getExpr(),
                                   (MCFixupKind)gpumin::fixup_gpumin_16_pcrel,
                                   /*IsPCRel=*/true));
  return 0;
}

uint64_t GPUMinMCCodeEmitter::getCallTargetOpValue(
    const MCInst &MI, unsigned OpNo, SmallVectorImpl<MCFixup> &Fixups,
    const MCSubtargetInfo &STI) const {
  const MCOperand &MO = MI.getOperand(OpNo);
  // Direct calls only: the J format has no register form, so a callee is
  // always a symbol and always needs the layout pass to compute its offset.
  assert(MO.isExpr() && "call target must be a symbol");

  Fixups.push_back(MCFixup::create(/*Offset=*/0, MO.getExpr(),
                                   (MCFixupKind)gpumin::fixup_gpumin_21_pcrel,
                                   /*IsPCRel=*/true));
  return 0;
}

MCCodeEmitter *llvm::createGPUMinMCCodeEmitter(MCContext &Ctx,
                                              const MCInstrInfo &MII) {
  return new GPUMinMCCodeEmitter(Ctx, MII);
}

#define ENABLE_INSTR_PREDICATE_VERIFIER
#include "GPUMinGenMCCodeEmitter.inc"
